-- RATHOD HUB central service locker. Run once in Supabase SQL Editor.
create table if not exists public.rh_system_control (
  id text primary key default 'global' check (id='global'),
  master_enabled boolean not null default true,
  hub_enabled boolean not null default true,
  quiz_bot_enabled boolean not null default true,
  sakhi_enabled boolean not null default true,
  pdf_worker_enabled boolean not null default true,
  maintenance_message text not null default 'System maintenance चल रहा है। कृपया थोड़ी देर बाद आएँ।',
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id)
);
insert into public.rh_system_control(id) values('global') on conflict(id) do nothing;
create table if not exists public.rh_control_members(user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in ('owner','manager')), active boolean not null default true, created_at timestamptz not null default now(), created_by uuid references auth.users(id));
create table if not exists public.rh_control_audit(id bigint generated by default as identity primary key, actor_id uuid references auth.users(id), action text not null, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table public.rh_system_control enable row level security; alter table public.rh_control_members enable row level security; alter table public.rh_control_audit enable row level security;
drop policy if exists rh_control_public_read on public.rh_system_control; create policy rh_control_public_read on public.rh_system_control for select using(true);
drop policy if exists rh_members_self_read on public.rh_control_members; create policy rh_members_self_read on public.rh_control_members for select using(auth.uid()=user_id);
drop policy if exists rh_audit_member_read on public.rh_control_audit; create policy rh_audit_member_read on public.rh_control_audit for select using(exists(select 1 from public.rh_control_members m where m.user_id=auth.uid() and m.active));
create or replace function public.bootstrap_rathod_owner() returns boolean language plpgsql security definer set search_path=public,auth as $$ begin if lower(coalesce(auth.jwt()->>'email',''))<>'ashisharmy1982@gmail.com' then raise exception 'Owner account required'; end if; insert into public.rh_control_members(user_id,role,active,created_by) values(auth.uid(),'owner',true,auth.uid()) on conflict(user_id) do update set role='owner',active=true; return true; end $$;
create or replace function public.get_rathod_system_control() returns jsonb language sql security definer set search_path=public as $$ select to_jsonb(c)||jsonb_build_object('can_control',exists(select 1 from rh_control_members m where m.user_id=auth.uid() and m.active),'control_role',(select role from rh_control_members m where m.user_id=auth.uid() and m.active)) from rh_system_control c where id='global' $$;
create or replace function public.set_rathod_system_control(p_master boolean default null,p_hub boolean default null,p_quiz_bot boolean default null,p_sakhi boolean default null,p_pdf_worker boolean default null,p_message text default null) returns jsonb language plpgsql security definer set search_path=public as $$ declare r text; outrow rh_system_control; begin select role into r from rh_control_members where user_id=auth.uid() and active; if r not in ('owner','manager') then raise exception 'Controller access required'; end if; update rh_system_control set master_enabled=coalesce(p_master,master_enabled),hub_enabled=coalesce(p_hub,hub_enabled),quiz_bot_enabled=coalesce(p_quiz_bot,quiz_bot_enabled),sakhi_enabled=coalesce(p_sakhi,sakhi_enabled),pdf_worker_enabled=coalesce(p_pdf_worker,pdf_worker_enabled),maintenance_message=coalesce(nullif(trim(p_message),''),maintenance_message),updated_at=now(),updated_by=auth.uid() where id='global' returning * into outrow; insert into rh_control_audit(actor_id,action,details) values(auth.uid(),'set_control',to_jsonb(outrow)); return to_jsonb(outrow); end $$;
create or replace function public.grant_rathod_controller(p_email text,p_role text default 'manager') returns boolean language plpgsql security definer set search_path=public,auth as $$ declare target uuid; begin if not exists(select 1 from public.rh_control_members where user_id=auth.uid() and role='owner' and active) then raise exception 'Owner only'; end if; if p_role not in ('owner','manager') then raise exception 'Invalid role'; end if; select id into target from auth.users where lower(email)=lower(trim(p_email)); if target is null then raise exception 'User must sign up first'; end if; insert into public.rh_control_members(user_id,role,active,created_by) values(target,p_role,true,auth.uid()) on conflict(user_id) do update set role=excluded.role,active=true,created_by=auth.uid(); insert into public.rh_control_audit(actor_id,action,details) values(auth.uid(),'grant',jsonb_build_object('email',p_email,'role',p_role)); return true; end $$;
create or replace function public.revoke_rathod_controller(p_email text) returns boolean language plpgsql security definer set search_path=public,auth as $$ declare target uuid; begin if not exists(select 1 from public.rh_control_members where user_id=auth.uid() and role='owner' and active) then raise exception 'Owner only'; end if; select id into target from auth.users where lower(email)=lower(trim(p_email)); update public.rh_control_members set active=false where user_id=target and role<>'owner'; insert into public.rh_control_audit(actor_id,action,details) values(auth.uid(),'revoke',jsonb_build_object('email',p_email)); return true; end $$;
grant execute on function public.bootstrap_rathod_owner() to authenticated; grant execute on function public.get_rathod_system_control() to anon,authenticated,service_role; grant execute on function public.set_rathod_system_control(boolean,boolean,boolean,boolean,boolean,text) to authenticated; grant execute on function public.grant_rathod_controller(text,text) to authenticated; grant execute on function public.revoke_rathod_controller(text) to authenticated;